import { functions } from '../firebase';
import { httpsCallable } from 'firebase/functions';

class StripeService {
  constructor() {
    // Inicializar las referencias a las Cloud Functions
    this.createConnectAccountFn = httpsCallable(functions, 'createConnectAccount');
    this.getOnboardingStatusFn = httpsCallable(functions, 'getOnboardingStatus');
    this.createPaymentIntentFn = httpsCallable(functions, 'createPaymentIntent');
    this.claimPrizeFn = httpsCallable(functions, 'claimPrize');
    this.getMyPrizesFn = httpsCallable(functions, 'getMyPrizes');
    this.getPlatformBalanceFn = httpsCallable(functions, 'getPlatformBalance');
  }

  // Crear cuenta Connect Express para un usuario
  async createConnectAccount(email, fullName, country = 'MX') {
    try {
      const result = await this.createConnectAccountFn({ email, fullName, country });
      return result.data;
    } catch (error) {
      console.error('Error creating Connect account:', error);
      throw new Error(error.message);
    }
  }

  // Obtener estado de onboarding de Stripe
  async getOnboardingStatus() {
    try {
      const result = await this.getOnboardingStatusFn();
      return result.data;
    } catch (error) {
      console.error('Error getting onboarding status:', error);
      throw new Error(error.message);
    }
  }

  // Crear PaymentIntent para pagos (inscripciones, cursos)
  async createPaymentIntent(amount, currency = 'usd', metadata = {}) {
    try {
      const result = await this.createPaymentIntentFn({ amount, currency, metadata });
      return result.data;
    } catch (error) {
      console.error('Error creating payment intent:', error);
      throw new Error(error.message);
    }
  }

  // Reclamar premio con código
  async claimPrize(prizeCode) {
    try {
      const result = await this.claimPrizeFn({ prizeCode });
      return result.data;
    } catch (error) {
      console.error('Error claiming prize:', error);
      throw new Error(error.message);
    }
  }

  // Obtener premios del usuario
  async getMyPrizes() {
    try {
      const result = await this.getMyPrizesFn();
      return result.data;
    } catch (error) {
      console.error('Error getting prizes:', error);
      throw new Error(error.message);
    }
  }

  // Obtener balance de la plataforma (solo admin)
  async getPlatformBalance() {
    try {
      const result = await this.getPlatformBalanceFn();
      return result.data;
    } catch (error) {
      console.error('Error getting platform balance:', error);
      throw new Error(error.message);
    }
  }
}

export default new StripeService();
